let K = OeeFacts(_startTime, _endTime)
    | summarize samples = sum(samples), running = sum(running), ideal = sum(ideal), actual = sum(actual), completed = sum(completed), rejected = sum(rejected)
    | invoke OeeKpis();
let a = toscalar(K | project Availability * 100);
let p = toscalar(K | project Performance * 100);
let q = toscalar(K | project Quality * 100);
union
    (print stage = "1 - Theoretical Max",     value = 100.0),
    (print stage = "2 - After Availability",  value = round(a, 2)),
    (print stage = "3 - After Performance",   value = round(a * p / 100.0, 2)),
    (print stage = "4 - OEE (after Quality)", value = round(a * p * q / 10000.0, 2))

let parts = PartEvents | where timestamp between (_startTime .. _endTime);
let finished = toscalar(parts | where action == "completed" | lookup kind=inner (LineMaster | project line_id, station_count) on line_id | where station_position == station_count | count);
let rejected = toscalar(parts | where action == "rejected" | count);
let status = MachineEvents | where timestamp between (_startTime .. _endTime) | summarize arg_max(timestamp, machine_status) by device_id;
union (print order = 1, Metric = "Parts finished", Value = finished),
      (print order = 2, Metric = "Parts rejected", Value = rejected),
      (print order = 3, Metric = "Stations running", Value = toscalar(status | where machine_status == "Running" | count)),
      (print order = 4, Metric = "Stations idle", Value = toscalar(status | where machine_status == "Idle" | count)),
      (print order = 5, Metric = "Stations down", Value = toscalar(status | where machine_status in ("Fault", "Maintenance") | count))
| order by order asc
| project Metric, Value
